class Solution {
  public boolean isIsomorphic(String s, String t) {
    int[] st = new int[256], ts = new int[256];
    for (int i = 0; i < s.length(); i++) {
      char a = s.charAt(i), b = t.charAt(i);
      if (st[a] == 0 && ts[b] == 0) {
        st[a] = b + 1;
        ts[b] = a + 1;
      } else if (st[a] != b + 1 || ts[b] != a + 1) return false;
    }
    return true;
  }
}
